     5	import java.math.BigDecimal;
     6	import java.time.YearMonth;
     7	import java.util.ArrayList;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/**
    12	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
    13	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
    14	 */
    15	public final class RevenueReport {
    16	
    17	    private final ReservationStore store;
    18	
    19	    public RevenueReport(ReservationStore store) {
    20	        this.store = store;
    21	    }
    22	
    23	    public String generate(YearMonth month) {
    24	        List<Reservation> withRevenue = new ArrayList<>();
    25	        for (Reservation reservation : store.all()) {
    26	            boolean keptMoney = reservation.amountKept().signum() > 0;
    27	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    28	            if (keptMoney && startsInMonth) {
    29	                withRevenue.add(reservation);
    30	            }
    31	        }
    32	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    33	
    34	        StringBuilder csv = new StringBuilder();
    35	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    36	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
    37	        for (Reservation reservation : withRevenue) {
    38	            csv.append(reservation.id()).append(',')
    39	                    .append(reservation.roomNumber()).append(',')
    40	                    .append(reservation.checkIn()).append(',')
    41	                    .append(reservation.checkOut()).append(',')
    42	                    .append(reservation.status()).append(',')
    43	                    .append(reservation.amountKept().toPlainString()).append('\n');
    44	            revenue = revenue.add(reservation.amountKept());
    45	        }
    46	        csv.append("total,").append(revenue.toPlainString()).append('\n');
    47	        return csv.toString();
    48	    }
    49	}
