65	     1	package hotel.reservations;
66	     2	
67	     3	import hotel.rooms.Room;
68	     4	import java.math.BigDecimal;
69	     5	import java.math.RoundingMode;
70	     6	import java.time.LocalDate;
71	     7	import java.time.Month;
72	     8	
73	     9	/**
74	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
75	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
76	    12	 * (half-even) at every step.
77	    13	 */
78	    14	public final class PriceCalculator {
79	    15	
80	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
81	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
82	    18	
83	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
84	    20	        int nights = 0;
85	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
86	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
87	    23	            subtotal = subtotal.add(nightPrice(room, night));
88	    24	            nights++;
89	    25	        }
90	    26	        BigDecimal discount = switch (ratePlan) {
91	    27	            case STANDARD -> cents(BigDecimal.ZERO);
92	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
93	    29	        };
94	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
95	    31	    }
96	    32	
97	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
98	    34	        BigDecimal nightlyRate = room.nightlyRate();
99	    35	        if (isHighSeason(night)) {
100	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
101	    37	        }
102	    38	        return cents(nightlyRate);
103	    39	    }
104	    40	
